'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/radio/md-gb-radio.js';
import {RadioElement} from '@material/web/labs/gb/components/radio/radio-element.js';

/**
 * A Material Design component. Wraps <md-gb-radio>.
 * Docs: https://material-web.dev/3.0/components/radio/
 */
export const MdRadio = createComponent({
  react: React,
  tagName: 'md-gb-radio',
  elementClass: RadioElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onInput: 'input' as EventName<InputEvent>,
  },
});

export type MdRadioProps = React.ComponentProps<typeof MdRadio>;
